\hspace*{1.5em}$\displaystyle M_2 = \frac{1.26\ \text{g} \times 0.083\ \text{L bar K}^{-1}\ \text{mol}^{-1} \times 300\ \text{K}}{2.57{\times}10^{-3}\text{bar} \times 0.200\ \text{L}} = 61{,}022\ \text{g mol}^{-1}$
\end{minipage}
